/bin/bash -lc "node - <<'JS'
try {
  const MarkdownIt = require('markdown-it');
  const md = new MarkdownIt().enable('table');
  const docs = {
    pipes: '## Stage ledger\\n\\n| Stage | Stated bound | Proved bound | Disposition |\\n|---|---|---|---|\\n| Good | x | x | sharp |\\n| Bad | x | x | invalid |\\n---\\n',
    noPipes: '## Stage ledger\\n\\n| Stage | Stated bound | Proved bound | Disposition |\\n|---|---|---|---|\\n| Good | x | x | sharp |\\nBad\\n---\\n'
  };
  for (const [name, text] of Object.entries(docs)) {
    console.log('---'+name+'---');
    console.log(md.render(text));
  }
} catch (e) {
  console.log(e.name + ': ' + e.message);
}
JS"

