/bin/bash -lc "python3 - <<'PY'
from markdown_it import MarkdownIt
md = MarkdownIt('commonmark').enable('table')
docs = {
    'pipes': '## Stage ledger\\n\\n| Stage | Stated bound | Proved bound | Disposition |\\n|---|---|---|---|\\n| Good | x | x | sharp |\\n| Bad | x | x | invalid |\\n---\\n',
    'no_pipes': '## Stage ledger\\n\\n| Stage | Stated bound | Proved bound | Disposition |\\n|---|---|---|---|\\n| Good | x | x | sharp |\\nBad\\n---\\n',
    'appendix_after_table': '## Stage ledger\\n\\n| Stage | Stated bound | Proved bound | Disposition |\\n|---|---|---|---|\\n| Good | x | x | sharp |\\nAppendix\\n--------\\n',
}
for name, text in docs.items():
    print(f'--- {name} ---')
    for token in md.parse(text):
        if token.type in {'table_open', 'tr_open', 'td_open', 'inline', 'table_close', 'hr', 'heading_open', 'heading_close'}:
            print(token.type, token.map, repr(token.content), token.tag)
PY"

